Records.CreateIndexStatement:
IF ISNULL(CONVERT(nvarchar(128), SERVERPROPERTY(N'ServerName')), N'') COLLATE Latin1_General_100_BIN2 <> N'demo' COLLATE Latin1_General_100_BIN2
    THROW 50001, 'INDEX_TARGET_SERVER_MISMATCH', 1;
CREATE NONCLUSTERED INDEX [IX_Orders_Review]
ON [Commerce].[dbo].[Orders] ([OrderDate], [CustomerId])
INCLUDE ([Amount])
WITH (ONLINE = OFF, DATA_COMPRESSION = ROW, SORT_IN_TEMPDB = OFF, MAXDOP = 2);

